            if (r,c) not in visited:
                q = deque([(r,c)])
                comp = [(r,c)]
                visited.add((r,c))
                while q:
                    cr, cc = q.popleft()
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < len(g) and 0 <= nc < len(g[0]) and (nr,nc) not in visited:
                            if g[nr][nc] == g[cr][cc]:
                                visited.add((nr,nc))
                                comp.append((nr,nc))
                                q.append((nr,nc))
                if len(comp) == 1:
                    scatted.add((r,c))
    return scatted

